<?php // Internal render: variabel berasal dari kbm_dashboard_payload, bukan input HTML siswa. ?>
<?php if(!$shown): ?><div class="alert alert-info mb-0">Tidak ada kelas yang sesuai filter. Ubah filter untuk menampilkan kelas lainnya.</div><?php endif ?>
<?php foreach($groups as $key=>$cards): if(!$cards)continue; ?>
<section class="kbm-session mb-4" data-session="<?= kbm_board_h($key) ?>"><div class="d-flex gap-2 align-items-center mb-3"><h2 class="h5 fw-bold mb-0"><i class="fa-solid fa-<?= $key==='pagi'?'sun':($key==='siang'?'cloud-sun':'sliders') ?> me-2 text-primary" aria-hidden="true"></i><?= ['pagi'=>'Sesi Pagi','siang'=>'Sesi Siang','belum_diatur'=>'Sesi belum diatur / perlu diperiksa'][$key] ?></h2><span class="badge bg-light text-dark border"><?= count($cards) ?> kelas</span></div><div class="kbm-grid">
<?php foreach($cards as $card): $state=$card['state'];$status=$state['primary'];$meeting=$state['meeting']; ?>
<article class="kbm-class-card kbm-color-<?= kbm_board_h($status['color']) ?>" data-class-id="<?= (int)$card['class']['id'] ?>" data-status="<?= kbm_board_h($status['code']) ?>"><div class="d-flex justify-content-between gap-2"><h3><?= kbm_board_h($card['class']['nama_kelas']) ?></h3><i class="fa-solid fa-<?= kbm_board_h($status['icon']) ?>" aria-hidden="true"></i></div><div class="teacher"><?= kbm_board_h($meeting['nama_guru']??'—') ?></div><div class="small mt-1"><?= kbm_board_h($meeting['nama_mapel']??'Tidak ada blok berjalan / berikutnya') ?></div><div class="small mt-2"><?= kbm_board_h($card['context']['sessions']?implode(' / ',array_map('ucfirst',$card['context']['sessions'])):'Sesi belum diatur') ?><?php if($meeting): ?> · JP <?= (int)$meeting['jp_mulai'] ?>–<?= (int)$meeting['jp_selesai'] ?><br><?= kbm_board_h($meeting['rencana_mulai']===null?'Tanpa jadwal jam':substr($meeting['rencana_mulai'],11,5).'–'.substr($meeting['rencana_selesai'],11,5).' WIB') ?><?php endif ?></div>
<span class="state-label"><?= kbm_board_h($status['label']) ?></span>
<?php if($meeting): ?><div class="kbm-times small mt-2">Check-in: <strong><?= kbm_board_h($meeting['checkin_efektif']??'Belum tercatat') ?></strong><br>Check-out: <strong><?= kbm_board_h($meeting['checkout_efektif']??'Belum tercatat') ?></strong></div><?php endif ?>
<?php if($status['warning']): ?><div class="pending-note fw-semibold"><?= kbm_board_h($status['warning']) ?></div><?php endif ?>
<?php if($card['context']['incomplete']): ?><div class="config-note mt-3"><strong><i class="fa-solid fa-sliders me-1" aria-hidden="true"></i>Konfigurasi belum lengkap</strong><ul class="mb-0 mt-1 ps-3"><?php foreach($card['context']['issues'] as $issue): ?><li><?= kbm_board_h($issue) ?></li><?php endforeach ?></ul></div><?php endif ?>
<?php foreach($state['warnings'] as $warning): $m=$warning['meeting']; ?><div class="pending-note"><strong><i class="fa-solid fa-triangle-exclamation me-1" aria-hidden="true"></i><?= kbm_board_h($warning['label']) ?></strong><br><?= kbm_board_h($m['tanggal'].' · JP '.$m['jp_mulai'].'–'.$m['jp_selesai'].' · '.$m['nama_guru']) ?><br><?= kbm_board_h($m['nama_mapel']) ?><br>Masuk: <?= kbm_board_h($m['checkin_efektif']) ?> · Belum check-out</div><?php endforeach ?>
<details class="mt-3" data-meeting-class="<?= (int)$card['class']['id'] ?>"><summary>Jadwal &amp; catatan (<?= count($card['meetings']) ?>)</summary><?php if(!$card['meetings']): ?><p class="small mt-2 mb-0"><?= $card['context']['incomplete']?'Lengkapi konfigurasi sebelum jadwal dapat ditampilkan.':'Tidak ada jadwal KBM pada tanggal ini.' ?></p><?php endif ?><?php foreach($card['meetings'] as $r): $s=$r['status']; ?><div class="meeting-line"><strong>JP <?= (int)$r['jp_mulai'] ?>–<?= (int)$r['jp_selesai'] ?> · <?= kbm_board_h($r['nama_mapel']) ?></strong><br><?= kbm_board_h($r['nama_guru']) ?><br><?= kbm_board_h($r['rencana_mulai']===null?'Tanpa jadwal jam':substr($r['rencana_mulai'],11,5).'–'.substr($r['rencana_selesai'],11,5).' WIB') ?><br><span class="badge bg-<?= kbm_board_h($s['bootstrap']) ?> <?= $s['bootstrap']==='warning'?'text-dark':'' ?>"><?= kbm_board_h($s['label']) ?></span><?php if($s['warning']): ?><div class="mt-1 fw-semibold"><?= kbm_board_h($s['warning']) ?></div><?php endif ?><div class="mt-1">Masuk: <?= kbm_board_h($r['checkin_efektif']??'Belum tercatat') ?><br>Selesai: <?= kbm_board_h($r['checkout_efektif']??'Belum tercatat') ?></div></div><?php endforeach ?></details><button class="kbm-card-open" type="button" data-kbm-open="<?= (int)$card['class']['id'] ?>" aria-label="<?= kbm_board_h('Buka detail '.$card['class']['nama_kelas'].'. '.$status['label'].($card['context']['incomplete']?'. Konfigurasi belum lengkap':'').(count($state['warnings'])?'. Ada catatan belum check-out':'')) ?>"><span class="kbm-card-flags"><?= ($card['context']['incomplete'] && $status['code']!=='belum_dikonfigurasi')?'Perlu konfigurasi':'' ?><?= count($state['warnings'])?' ? Belum check-out':'' ?></span></button></article>
<?php endforeach ?>
</div></section>
<?php endforeach ?>
